'use strict';
// Preserve existing commands and event handlers when the available toolbar width changes.
const ucBars=new WeakMap();let ucFrame=0;
function ucFitBar(bar){if(bar.classList.contains('ra-result-commandbar'))return;const actions=bar.querySelector(':scope > .command-actions,:scope > .aw-command-actions,:scope > .ew-command-actions');if(!actions)return;let record=ucBars.get(bar);if(!record){const nodes=[...actions.childNodes],more=document.createElement('details');more.className='uc-command-more';more.innerHTML='<summary class="btn sm" aria-label="更多工具操作" aria-expanded="false">'+I('more','icon-sm')+'<span>更多</span></summary><div class="uc-command-menu" aria-label="其他工具操作"></div>';const menu=more.lastElementChild;record={nodes,more,menu};ucBars.set(bar,record);actions.append(more);more.addEventListener('toggle',()=>{more.firstElementChild.setAttribute('aria-expanded',String(more.open));if(more.open)ucPlaceMenu(more);});}
const {nodes,more,menu}=record;more.open=false;nodes.forEach(n=>actions.insertBefore(n,more));bar.classList.remove('uc-overflowing');more.hidden=true;const buttons=nodes.filter(n=>n.nodeType===1&&n.matches('button')),main=buttons.find(b=>b.matches('.primary'))||buttons.find(b=>b.dataset.action==='stop-task')||buttons.at(-1),aux=buttons.filter(b=>b!==main);buttons.forEach(b=>{if(!b.textContent.trim()&&!b.querySelector('.uc-menu-label')){const label=document.createElement('span');label.className='uc-menu-label';label.textContent=b.getAttribute('aria-label')||b.title||'操作说明';b.append(label);}if(b.dataset.action==='new-analysis'&&b.textContent.includes('复制')){const icon=b.querySelector('svg');if(icon?.dataset.icon!=='copy')icon?.replaceWith(document.createRange().createContextualFragment(I('copy','icon-sm')));}});
const fits=()=>{const r=bar.getBoundingClientRect(),ar=actions.getBoundingClientRect(),heading=bar.firstElementChild.getBoundingClientRect();return ar.right<=r.right-5&&ar.left>=heading.right+5&&actions.scrollWidth<=actions.clientWidth+1&&bar.scrollWidth<=bar.clientWidth+1;};
if(!fits()){bar.classList.add('uc-overflowing');more.hidden=false;const order=[...aux].sort((a,b)=>{const rank=x=>({help:0,'nav-tasks':1,'new-analysis':2,'aw-config':3,'ew-config':3,'add-tool-materials':4}[x.dataset.action]??5);return rank(a)-rank(b);});while(order.length&&!fits())menu.append(order.shift());if(!menu.children.length)more.hidden=true;}if(!menu.children.length)more.hidden=true;else{[...menu.children].sort((a,b)=>nodes.indexOf(a)-nodes.indexOf(b)).forEach(n=>menu.append(n));if(main)actions.insertBefore(more,main);}
}
function ucPlaceMenu(more){const menu=more.lastElementChild,r=more.firstElementChild.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(r.right-230,innerWidth-238))+'px';menu.style.top=Math.min(r.bottom+6,innerHeight-80)+'px';menu.style.maxHeight=Math.max(60,innerHeight-r.bottom-18)+'px';}
function ucLayout(){document.querySelectorAll('.work-commandbar,.ew-commandbar').forEach(ucFitBar);}
function ucSchedule(){cancelAnimationFrame(ucFrame);ucFrame=requestAnimationFrame(ucLayout);}
const ucBaseRender=render;render=function(){ucBaseRender();ucLayout();};
window.addEventListener('resize',ucSchedule);window.addEventListener('click',e=>{document.querySelectorAll('.uc-command-more[open]').forEach(d=>{if(!d.contains(e.target)||e.target.closest('[data-action]')){d.open=false;d.firstElementChild.setAttribute('aria-expanded','false');}});},true);
window.addEventListener('keydown',e=>{const open=document.querySelector('.uc-command-more[open]'),current=e.target.closest('.uc-command-more');if(e.key==='Escape'&&open&&!modal){e.preventDefault();e.stopImmediatePropagation();open.open=false;open.firstElementChild.focus();return;}if(!current)return;const entries=[...current.lastElementChild.querySelectorAll('button:not([disabled])')];if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(!current.open){current.open=true;ucPlaceMenu(current);}let index=entries.indexOf(document.activeElement);index=e.key==='Home'?0:e.key==='End'?entries.length-1:index<0?(e.key==='ArrowUp'?entries.length-1:0):(index+(e.key==='ArrowUp'?-1:1)+entries.length)%entries.length;entries[index]?.focus();}},true);
render();
